"use client";

import { useState } from "react";
import { useI18n } from "@/i18n/I18nProvider";
import type { DocumentId } from "@/lib/engine/types";
import { CheckCircleIcon, FileIcon } from "../Icons";
import type { Slots } from "./UploadView";

/** Scenario folders under public/samples/ (generated by `npm run samples`). */
export const SAMPLE_SCENARIOS = ["clean", "quantity-weight", "hs-code", "missing-info"] as const;
type Scenario = (typeof SAMPLE_SCENARIOS)[number];

const FILES: Record<DocumentId, string> = {
  invoice: "1-invoice.pdf",
  packingList: "2-packing-list.pdf",
  customsDocument: "3-customs-declaration.pdf",
};

/**
 * "Try sample documents": loads a scenario's three real PDFs into the upload
 * slots. Nothing is precomputed — the user then starts the normal check.
 */
export function SampleScenarios({ onLoad }: { onLoad: (slots: Slots) => void }) {
  const { dict } = useI18n();
  const t = dict.portal.samples;
  const [state, setState] = useState<{ id: Scenario; status: "loading" | "loaded" | "failed" } | null>(null);

  async function use(id: Scenario) {
    setState({ id, status: "loading" });
    try {
      const entries = await Promise.all(
        (Object.entries(FILES) as [DocumentId, string][]).map(async ([doc, name]) => {
          const res = await fetch(`/samples/${id}/${name}`, { cache: "no-store" });
          if (!res.ok) throw new Error(String(res.status));
          return [doc, new File([await res.blob()], `${id}-${name}`, { type: "application/pdf" })] as const;
        }),
      );
      onLoad(Object.fromEntries(entries) as Slots);
      setState({ id, status: "loaded" });
      window.scrollTo({ top: 0, behavior: "smooth" });
    } catch {
      setState({ id, status: "failed" });
    }
  }

  return (
    <section className="samples" aria-labelledby="samples-title">
      <h2 id="samples-title" className="section-title">{t.title}</h2>
      <p className="fine-print samples__intro">{t.subtitle}</p>
      <div className="samples__grid">
        {SAMPLE_SCENARIOS.map((id) => {
          const s = t.scenarios[id];
          const mine = state?.id === id ? state.status : null;
          return (
            <article key={id} className={`samples__card ${mine === "loaded" ? "samples__card--loaded" : ""}`}>
              <h3 className="samples__name">
                {mine === "loaded" ? <CheckCircleIcon size={18} /> : <FileIcon size={18} />}
                {s.title}
              </h3>
              <p className="samples__text">{s.text}</p>
              <button type="button" className="btn btn--outline btn--sm" disabled={state?.status === "loading"} onClick={() => void use(id)}>
                {mine === "loading" ? t.loading : t.use}
              </button>
              {mine === "loaded" && <p className="samples__status" role="status">{t.loaded}</p>}
              {mine === "failed" && <p className="samples__status samples__status--error" role="alert">{t.failed}</p>}
            </article>
          );
        })}
      </div>
    </section>
  );
}
